// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public { c = new DnGmxBatchingManager(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        bool ok;
        address ret;
        vm.prank(caller);
        try c.owner() returns (address o) {
            ok = true;
            ret = o;
        } catch {
            ok = false;
            ret = address(0);
        }

        bool ok2;
        address canonical;
        try c.owner() returns (address o2) {
            ok2 = true;
            canonical = o2;
        } catch {
            ok2 = false;
            canonical = address(0);
        }

        assertTrue(ok && ok2 && ret == canonical);
    }
}
